#!/usr/bin/env python3
# -*- coding: utf-8 -*-
# patch_hook_ajuste.py -- anti-corte de letras (margem) + hook ancorado no topo do video.
import base64, py_compile, shutil, sys, time
from pathlib import Path
ALVO = Path(__file__).resolve().parent / "agents/narrated_video_agent.py"
PARES = [('', ''), ('', ''), ('ICAgICAgICB3aGlsZSBIS19GT05UID4gSEtfRk9OVF9NSU4gYW5kIG1heChfbGFyZyhsLCBIS19GT05UKSBmb3IgbCBpbiBfbGluaGFzKSA+IEhLX01BWF9MQVJHOgogICAgICAgICAgICBIS19GT05UIC09IDIKICAgIF9uID0gbGVuKF9saW5oYXMpCgogICAgX2hrX3Bvcl9saW5oYSA9IFtdCiAgICBmb3IgX2ksIF9saW5oYSBpbiBlbnVtZXJhdGUoX2xpbmhhcyk6', '')]
def main():
    if not ALVO.exists(): print("nao achei",ALVO); return 1
    txt = ALVO.read_text(encoding="utf-8").replace("\r\n","\n")
    pares=[(base64.b64decode(o).decode(),base64.b64decode(n).decode()) for o,n in PARES]
    if all(n in txt for _,n in pares): print("JA APLICADO"); return 0
    novo=txt
    for old,new in pares:
        if new in novo: continue
        if old not in novo: print("ABORTADO: bloco nao encontrado:"); print("  "+old.strip().splitlines()[0][:88]); return 2
        if novo.count(old)!=1: print("ABORTADO: bloco ambiguo:"); print("  "+old.strip().splitlines()[0][:88]); return 2
        novo=novo.replace(old,new)
    bak=ALVO.with_suffix(ALVO.suffix+".bak_"+time.strftime("%Y%m%d_%H%M%S"))
    shutil.copy2(ALVO,bak); ALVO.write_text(novo,encoding="utf-8")
    try: py_compile.compile(str(ALVO),doraise=True)
    except Exception as e: shutil.copy2(bak,ALVO); print("py_compile falhou, RESTAUREI:",e); return 3
    print("APLICADO (backup",bak.name,"). Reinicie: systemctl restart jarvis"); return 0
if __name__=="__main__": sys.exit(main())
